import { test } from '@playwright/test';
import { blockWrites, CONVERSATION_URL, expectConversationFillsMobileScreen, messageInput } from './open-conversation.helpers';

test.use({ storageState: '../auth/chat.json', serviceWorkers: 'block' });

test.describe('Чат / переписки — открытие переписки', () => {
  test('Мобайл: прямая ссылка на переписку сразу показывает переписку, а не меню «אזור אישי» #bb6e6d @mobile @prod-safe', async ({ page }) => {
    await blockWrites(page);
    await page.goto(CONVERSATION_URL);
    await messageInput(page).waitFor();
    await expectConversationFillsMobileScreen(page);
  });
});
